import React, { useEffect, useState, useCallback } from 'react';
import NotificationStrip from 'webapp/components/NotificationStrip';
import { useDashboardConfig } from 'webapp/hooks/useDashboardConfig';
import userPrefs from 'webapp/lib/userPrefs';

type ActiveBanner = {
  campaignId: string;
  title?: string;
  message: string;
  // other fields as returned by the API...
};

const DISMISSED_KEY_PREFIX = 'dashboardBannerDismissed:';

function useAnnouncementDismissal(campaignId?: string) {
  const [isDismissed, setIsDismissed] = useState<boolean>(false);

  useEffect(() => {
    if (!campaignId) {
      setIsDismissed(false);
      return;
    }
    const key = DISMISSED_KEY_PREFIX + campaignId;
    // userPrefs.get returns stored value or undefined; default to false
    const stored = userPrefs.get(key);
    setIsDismissed(Boolean(stored));
  }, [campaignId]);

  const dismiss = useCallback(
    (campaignIdToSet?: string) => {
      if (!campaignIdToSet) return;
      const key = DISMISSED_KEY_PREFIX + campaignIdToSet;
      try {
        userPrefs.set(key, true);
      } catch (e) {
        // keep behavior silent on storage errors (mirrors previous pattern)
      }
      setIsDismissed(true);
    },
    []
  );

  return { isDismissed, dismiss };
}

export default function AnnouncementBanner(): JSX.Element | null {
  // useDashboardConfig is our existing hook that provides marketing banner data
  const { data: dashboardConfig } = useDashboardConfig(); // adapt to existing return shape
  const activeBanner = (dashboardConfig && (dashboardConfig as any).activeBanner) as ActiveBanner | null;

  const campaignId = activeBanner?.campaignId;
  const { isDismissed, dismiss } = useAnnouncementDismissal(campaignId);

  // If there's no active banner, behave as before (render nothing)
  if (!activeBanner) return null;

  // If this campaign was dismissed, don't render
  if (isDismissed) return null;

  // Close handler wired to the NotificationStrip action (e.g. "Got it" or close icon)
  const onClose = () => {
    if (campaignId) dismiss(campaignId);
  };

  return (
    <NotificationStrip
      variant="info"
      title={activeBanner.title}
      onClose={onClose}
      // Keep other props consistent with existing usage
    >
      <div>{activeBanner.message}</div>
    </NotificationStrip>
  );
}
```

