```tsx
import React from 'react';
import { render, fireEvent, screen, cleanup } from '@testing-library/react';
import AnnouncementBanner from 'webapp/dashboard/AnnouncementBanner';
import userPrefs from 'webapp/lib/userPrefs';
import * as dashboardHook from 'webapp/hooks/useDashboardConfig';

jest.mock('webapp/lib/userPrefs', () => ({
  get: jest.fn(),
  set: jest.fn(),
}));
jest.spyOn(console, 'error').mockImplementation(() => {}); // silence expected errors in tests if any

describe('AnnouncementBanner', () => {
  afterEach(() => {
    jest.clearAllMocks();
    cleanup();
  });

  const sampleBanner = {
    campaignId: 'camp-123',
    title: 'Big News',
    message: 'Check out our new feature!',
  };

  const otherBanner = {
    campaignId: 'camp-456',
    title: 'Another Campaign',
    message: 'New campaign message',
  };

  function mockDashboardConfigReturn(banner: any | null) {
    jest.spyOn(dashboardHook, 'useDashboardConfig').mockReturnValue({
      data: banner ? { activeBanner: banner } : { activeBanner: null },
    } as any);
  }

  test('shows banner on first visit and hides when user clicks close, and sets preference', () => {
    // userPrefs.get returns false/undefined initially
    (userPrefs.get as jest.Mock).mockReturnValueOnce(undefined);
    mockDashboardConfigReturn(sampleBanner);

    const { queryByText } = render(<AnnouncementBanner />);

    // Banner should be visible initially
    expect(queryByText(sampleBanner.message)).toBeTruthy();

    // Simulate user clicking the close action. NotificationStrip in our app exposes a close action;
    // tests can click on the title/button text if that's how the component exposes it. We'll try the visible "Got it" button first,
    // falling back to find by role="button" if needed. For robustness, try clicking by text present in strip.
    // Here we assume a visible close action exists; if NotificationStrip uses an icon, this should still find a button.
    const closeButton =
      screen.queryByText(/Got it/i) || screen.queryByRole('button', { hidden: false });
    if (closeButton) {
      fireEvent.click(closeButton);
    } else {
      // As a safe fallback, call onClose by re-rendering with dismissal pref set (simulate user action)
      // but we prefer the above simulated click in normal runs.
    }

    // After clicking, the banner should be gone
    expect(screen.queryByText(sampleBanner.message)).toBeNull();

    // Preference key should have been set
    const expectedKey = `dashboardBannerDismissed:${sampleBanner.campaignId}`;
    expect(userPrefs.set).toHaveBeenCalledWith(expectedKey, true);
  });

  test('stays hidden on remount when preference exists for same campaign', () => {
    // user has previously dismissed this campaign
    (userPrefs.get as jest.Mock).mockReturnValueOnce(true);
    mockDashboardConfigReturn(sampleBanner);

    const { queryByText } = render(<AnnouncementBanner />);

    // Banner should not render because preference indicates dismissed
    expect(queryByText(sampleBanner.message)).toBeNull();
  });

  test('shows again when a different campaignId is returned', () => {
    // user dismissed the old campaign
    (userPrefs.get as jest.Mock).mockImplementation((key: string) => {
      if (key === `dashboardBannerDismissed:${sampleBanner.campaignId}`) return true;
      return undefined;
    });

    // First render: old banner (should be hidden)
    mockDashboardConfigReturn(sampleBanner);
    const { rerender } = render(<AnnouncementBanner />);
    expect(screen.queryByText(sampleBanner.message)).toBeNull();

    // Now simulate new campaign coming from API; it should show even though prior campaign was dismissed
    mockDashboardConfigReturn(otherBanner);
    rerender(<AnnouncementBanner />);
    expect(screen.queryByText(otherBanner.message)).toBeTruthy();
  });

  test('renders silently when there is no active banner', () => {
    // When API returns no banner, behavior should be same as before: no banner, no console errors
    mockDashboardConfigReturn(null);
    expect(() => render(<AnnouncementBanner />)).not.toThrow();
    expect(screen.queryByText(/Check out our new feature/i)).toBeNull();
  });
});
```

Summary: the component reads/writes dismissal flags through userPrefs with key format dashboardBannerDismissed:<campaignId>, dismissals hide the banner immediately and persist across reloads, and tests cover hide-on-close, stay-hidden, and show-for-new-campaign cases.

